use super::*;
use crate::money::Money;

/// What the projection says is safe to commit to per month.
///
/// The LOW of the FURTHEST month, because a commitment made now has to survive the least certain
/// month it reaches. Taking month one's low would price a twelve-month commitment off the one month
/// the projection knows most about.
pub fn committable_monthly(p: &IncomeProjection) -> Option<Money> {
    if !p.projectable {
        return None;
    }
    p.months.last().map(|b| b.low)
}
